package events

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// PutSnapshotVersion binds an existing snapshot of documentID to the stable
// version name, all inside one serialized transaction.
//
// The gate (registration then permission) is taken first in the transaction:
// an unregistered device yields store.ErrDeviceNotFound and a revoked device
// store.ErrPermissionDenied, before any snapshot or version is observed. Then
// the target snapshot must exist (a miss, an unknown document included, is
// ErrSnapshotNotFound), and finally the name is resolved:
//
//   - an unbound name is inserted and reports the binding;
//   - a name already bound to the same cursor is idempotent and reports the
//     very same name/cursor pair (the HTTP body is byte-identical to the first
//     registration);
//   - a name already bound to another cursor is *ErrVersionConflict with zero
//     writes.
//
// A version marker never copies or moves snapshot bytes and creates no
// change.
func (s *Service) PutSnapshotVersion(documentID, deviceID, name string, cursor int64) (VersionResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return VersionResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return VersionResult{}, err
	}
	if err := snapshotExistsTx(tx, documentID, cursor); err != nil {
		return VersionResult{}, err
	}

	var existing sql.NullInt64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// An unbound name: insert below.
	case err != nil:
		return VersionResult{}, err
	case existing.Int64 != cursor:
		return VersionResult{}, &ErrVersionConflict{Name: name}
	default:
		// Already bound to the same cursor: idempotent, zero writes.
		if err := tx.Commit(); err != nil {
			return VersionResult{}, err
		}
		return VersionResult{Name: name, Cursor: cursor}, nil
	}
	if _, err := tx.Exec(
		`INSERT INTO snapshot_versions (document_id, name, cursor) VALUES (?, ?, ?)`,
		documentID, name, cursor,
	); err != nil {
		return VersionResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return VersionResult{}, err
	}
	return VersionResult{Name: name, Cursor: cursor}, nil
}

// ListSnapshotVersions returns every version marker of documentID in
// ascending name order, together with the snapshot cursor each points at. The
// gate runs first in the transaction (404 for an unregistered device, 403 for
// a revoked one); an unknown document or a document without markers then
// reads as an empty list rather than an error. It writes nothing.
func (s *Service) ListSnapshotVersions(documentID, deviceID string) ([]SnapshotVersion, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return nil, err
	}

	rows, err := tx.Query(
		`SELECT name, cursor FROM snapshot_versions
		 WHERE document_id = ? ORDER BY name ASC`,
		documentID,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]SnapshotVersion, 0)
	for rows.Next() {
		var v SnapshotVersion
		if err := rows.Scan(&v.Name, &v.Cursor); err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, tx.Commit()
}

// GetSnapshotVersionState resolves a version name to its snapshot and returns
// that snapshot's cursor and stored state, exactly as GetSnapshot would for
// the cursor. The gate runs first; a name without a marker is
// ErrVersionNotFound and a marker whose snapshot is gone is
// ErrSnapshotNotFound — the caller maps both to 404 and exposes no content.
func (s *Service) GetSnapshotVersionState(documentID, deviceID, name string) (int64, json.RawMessage, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, nil, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return 0, nil, err
	}

	var cursor int64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&cursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return 0, nil, ErrVersionNotFound
	case err != nil:
		return 0, nil, err
	}

	var state []byte
	if err := tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return 0, nil, ErrSnapshotNotFound
		}
		return 0, nil, err
	}
	return cursor, json.RawMessage(state), tx.Commit()
}

// RebindSnapshotVersion moves an existing version name of documentID to
// another existing snapshot cursor in one serialized transaction. The gate
// (404/403) is taken first; the named marker must exist (ErrVersionNotFound)
// and the target snapshot must exist (ErrSnapshotNotFound, an unknown
// document included). Rebinding to the cursor already bound is an idempotent
// no-op reporting the same pair; otherwise the marker is updated. The
// snapshot itself is never modified or copied.
func (s *Service) RebindSnapshotVersion(documentID, deviceID, name string, cursor int64) (VersionResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return VersionResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return VersionResult{}, err
	}

	var existing int64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return VersionResult{}, ErrVersionNotFound
	case err != nil:
		return VersionResult{}, err
	}
	if err := snapshotExistsTx(tx, documentID, cursor); err != nil {
		return VersionResult{}, err
	}
	if existing != cursor {
		if _, err := tx.Exec(
			`UPDATE snapshot_versions SET cursor = ? WHERE document_id = ? AND name = ?`,
			cursor, documentID, name,
		); err != nil {
			return VersionResult{}, err
		}
	}
	if err := tx.Commit(); err != nil {
		return VersionResult{}, err
	}
	return VersionResult{Name: name, Cursor: cursor}, nil
}

// DeleteSnapshotVersion hard-deletes one version marker of documentID. The
// gate (404/403) is taken first; a name without a marker is
// ErrVersionNotFound. The snapshot is left untouched; once the marker commits
// the name is free to bind again.
func (s *Service) DeleteSnapshotVersion(documentID, deviceID, name string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return err
	}

	var bound int64
	if err := tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&bound); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrVersionNotFound
		}
		return err
	}
	if _, err := tx.Exec(
		`DELETE FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// RestoreSnapshotVersion resolves a version name of documentID to its
// snapshot and appends that snapshot's state as one ordinary change, with
// exactly the semantics of RestoreSnapshot: the gate is taken first in the
// transaction, a missing marker yields ErrVersionNotFound and a missing
// snapshot ErrSnapshotNotFound, after which the shared restore path decides
// idempotency and conflict (an id occupied by an ordinary change is 409). The
// document cursor advances by one on a genuinely new restore and the long
// polls and subscribers are woken.
func (s *Service) RestoreSnapshotVersion(documentID, deviceID, changeID, name string) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return RestoreResult{}, err
	}

	var snapshotCursor int64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&snapshotCursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return RestoreResult{}, ErrVersionNotFound
	case err != nil:
		return RestoreResult{}, err
	}

	result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
	if err != nil {
		return RestoreResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	if result.Created {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// gateTx runs the service's registration/permission gate inside tx. A service
// built without a gate (some service-level tests) skips the verdict.
func gateTx(s *Service, tx *sql.Tx, documentID, deviceID string) error {
	if s.gate == nil {
		return nil
	}
	return s.gate.DeviceAuthorizedTx(tx, documentID, deviceID)
}

// snapshotExistsTx reports whether documentID has a snapshot at cursor,
// returning ErrSnapshotNotFound on a miss. It runs inside the caller's
// serialized transaction so the existence verdict and the following write are
// one judgment.
func snapshotExistsTx(tx *sql.Tx, documentID string, cursor int64) error {
	var state []byte
	if err := tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrSnapshotNotFound
		}
		return err
	}
	return nil
}

package events

import (
	"bytes"
	"database/sql"
	"encoding/json"
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// PutSnapshot stores state as the snapshot of documentID at cursor, creating
// it on first use and reporting whether this call created it.
//
// Only cursors of existing changes are valid snapshot points: an unknown
// document, a cursor below 1 or a cursor ahead of the document's current
// cursor yields ErrSnapshotBase and nothing is written. The current cursor is
// the document's high-water mark in the never-reset cursor space — the
// greater of the online maximum and the compaction boundary — so a cursor
// whose change has been trimmed by compaction is still a valid snapshot
// point, even after a full trim emptied the online log. Re-posting a state
// that decodes equal to the stored one is idempotent (created=false); a
// different state is an *ErrSnapshotConflict and the stored snapshot is left
// unchanged. Snapshots are independent of the change log: they neither move
// the document's cursor nor affect merges.
func (s *Service) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	current, err := currentCursorTx(tx, documentID)
	if err != nil {
		return false, err
	}
	if current == 0 || cursor < 1 || cursor > current {
		return false, ErrSnapshotBase
	}

	var existing []byte
	err = tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO snapshots (document_id, cursor, state) VALUES (?, ?, ?)`,
			documentID, cursor, []byte(state),
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	default:
		if !store.JSONEqual(existing, state) {
			return false, &ErrSnapshotConflict{Cursor: cursor}
		}
		return false, nil
	}
}

// GetSnapshot returns the state stored for documentID at cursor. Any miss —
// unknown document, unknown cursor or absent snapshot — yields
// ErrSnapshotNotFound.
func (s *Service) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
	var state []byte
	err := s.db.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrSnapshotNotFound
	case err != nil:
		return nil, err
	default:
		return json.RawMessage(state), nil
	}
}

// ExportSnapshots returns every snapshot of documentID whose cursor lies in
// the closed interval [from, to], in ascending cursor order. When to is nil no
// upper bound is applied. An unknown document, or a range without a snapshot,
// yields an empty list and no error: the export is a read that misses like any
// other. The (document_id, cursor) primary key guarantees a cursor appears at
// most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a snapshot committed concurrently is observed either with all
// of its row or not at all — never half of it. The read starts no
// transaction, writes nothing and notifies no waiters, so it cannot move a
// cursor or produce a change record.
func (s *Service) ExportSnapshots(documentID string, from int64, to *int64) ([]ExportedSnapshot, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT cursor, state FROM snapshots
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT cursor, state FROM snapshots
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ExportedSnapshot, 0)
	for rows.Next() {
		var snap ExportedSnapshot
		if err := rows.Scan(&snap.Cursor, &snap.State); err != nil {
			return nil, err
		}
		out = append(out, snap)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// RestoreSnapshot appends one ordinary change whose payload is the state of
// documentID's snapshot at snapshotCursor, all within a single serialized
// transaction.
//
//   - A snapshot miss (unknown document or a cursor without a snapshot)
//     returns ErrSnapshotNotFound; nothing is written.
//   - If changeID already belongs to a prior restore, the call is idempotent
//     only when deviceId, snapshotCursor and the decoded source state all
//     match; the first result (created=false, original cursor) is returned.
//   - If changeID is taken by an ordinary change, or a restore whose provenance
//     differs, the call returns *ErrRestoreConflict; nothing is written.
//
// Otherwise a new change is appended with the next document cursor and the
// restore provenance is recorded. Old rows are never modified.
func (s *Service) RestoreSnapshot(documentID, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
	if err != nil {
		return RestoreResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	// A genuinely new restore appended a change and is the only outcome that
	// wakes the long polls and pushes to subscribers; an idempotent repeat
	// appended nothing and notifies nothing.
	if result.Created {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// RestoreSnapshotAuthorized is the session-scoped restore: it has exactly the
// restore semantics of RestoreSnapshot, but enforces the gate (registration
// then permission) first in the same serialized transaction: an unregistered
// device yields store.ErrDeviceNotFound and a revoked device yields
// ErrPermissionDenied. None of those outcomes writes anything or observes
// snapshot or change content. The device identity is resolved from the session
// by the HTTP layer before the call.
func (s *Service) RestoreSnapshotAuthorized(documentID, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before the
	// snapshot is looked up or any change content is observed, so a rejected
	// restore cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return RestoreResult{}, err
		}
	}

	result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
	if err != nil {
		return RestoreResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	if result.Created {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// restoreSnapshotTx runs the snapshot lookup, the idempotency/conflict
// resolution and the single append inside the caller's serialized
// transaction. It is shared by the document-level restore and the
// session-scoped authorized restore so the two paths cannot drift: both take
// their snapshot miss (ErrSnapshotNotFound), conflict (*ErrRestoreConflict)
// and append decisions from one code path. The result's Created flag tells
// the caller whether a change-bearing transaction just committed and the push
// channels therefore need waking.
func restoreSnapshotTx(tx *sql.Tx, documentID, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	// The snapshot must exist; its state is the payload to append.
	var state []byte
	err := tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, snapshotCursor,
	).Scan(&state)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return RestoreResult{}, ErrSnapshotNotFound
	case err != nil:
		return RestoreResult{}, err
	}

	// Resolve the change id: an ordinary row, a prior restore and a
	// compacted-away id's retained summary are handled differently, so consult
	// all three.
	var existingCursor int64
	var existingDevice string
	var existingPayload []byte
	err = tx.QueryRow(
		`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
		documentID, changeID,
	).Scan(&existingCursor, &existingDevice, &existingPayload)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No online row: the id may belong to a change compaction trimmed.
		// Its retained summary still decides — an idempotent restore needs the
		// same device, snapshot cursor and source state; an id left by an
		// ordinary trimmed change is a conflict, as is any mismatch.
		var summaryDevice string
		var summaryDigest []byte
		var summaryCursor int64
		var restoredFrom sql.NullInt64
		err := tx.QueryRow(
			`SELECT device_id, digest, cursor, restored_from FROM change_identities
			 WHERE document_id = ? AND id = ?`,
			documentID, changeID,
		).Scan(&summaryDevice, &summaryDigest, &summaryCursor, &restoredFrom)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// Genuinely new id; fall through to append below.
		case err != nil:
			return RestoreResult{}, err
		default:
			stateDigest, err := payloadDigest(state)
			if err != nil {
				return RestoreResult{}, err
			}
			if !restoredFrom.Valid || restoredFrom.Int64 != snapshotCursor ||
				summaryDevice != deviceID || !bytes.Equal(summaryDigest, stateDigest) {
				return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
			}
			return RestoreResult{
				ID:           changeID,
				Created:      false,
				Cursor:       summaryCursor,
				RestoredFrom: snapshotCursor,
			}, nil
		}
	case err != nil:
		return RestoreResult{}, err
	default:
		var restDevice string
		var restSnapshotCursor int64
		var restState []byte
		err = tx.QueryRow(
			`SELECT device_id, snapshot_cursor, state FROM restores WHERE document_id = ? AND change_id = ?`,
			documentID, changeID,
		).Scan(&restDevice, &restSnapshotCursor, &restState)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// The id belongs to an ordinary change (or a batch/merge change),
			// not a restore: never treat it as an idempotent restore.
			return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
		case err != nil:
			return RestoreResult{}, err
		default:
			if restDevice != deviceID || restSnapshotCursor != snapshotCursor || !store.JSONEqual(restState, state) {
				return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
			}
			return RestoreResult{
				ID:           changeID,
				Created:      false,
				Cursor:       existingCursor,
				RestoredFrom: snapshotCursor,
			}, nil
		}
	}

	nextCursor, err := currentCursorTx(tx, documentID)
	if err != nil {
		return RestoreResult{}, err
	}
	nextCursor++
	if _, err := tx.Exec(
		`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
		documentID, nextCursor, changeID, deviceID, state,
	); err != nil {
		return RestoreResult{}, err
	}
	if _, err := tx.Exec(
		`INSERT INTO restores (document_id, change_id, device_id, snapshot_cursor, change_cursor, state)
		 VALUES (?, ?, ?, ?, ?, ?)`,
		documentID, changeID, deviceID, snapshotCursor, nextCursor, state,
	); err != nil {
		return RestoreResult{}, err
	}
	return RestoreResult{
		ID:           changeID,
		Created:      true,
		Cursor:       nextCursor,
		RestoredFrom: snapshotCursor,
	}, nil
}

// Package store is the durable kernel shared by the internal services: it
// owns the SQLite database handle and the registration layer (devices and
// sessions) plus resumable attachments.
//
// The business services layered on top of the kernel — the change event log,
// the permission ledger and the CRDT state — live in their own packages and
// cooperate only through their internal interfaces. They all share this one
// handle: it opens a single pooled connection with immediate write
// transactions, so every service's transactional judgment is serialized on
// the same connection and no batch is ever half written.
//
// Devices and sessions form the registration layer. A device registers with a
// client-supplied id; a session belongs to exactly one registered device and
// is addressed by its own client-supplied id. Registration and session
// creation are idempotent re-posts: the first call creates, an identical
// repeat does not. A session id already owned by another device is a
// conflict, never silently re-homed. Deletes are owner-scoped and hard: a
// repeat delete, another device, and a cross-device path all miss with 404,
// after which the id is free to be created again. A device itself can
// deregister: the device row and everything it owns — its sessions and the
// attachments it created, chunks and grants included — vanish in one
// serialized transaction, a repeat or never-registered deregistration misses
// with 404 and writes nothing, and the freed id registers again as a
// brand-new device.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them. The creator may grant
// other registered devices read-only access per attachment; every
// (attachment, device) pair starts unauthorized, grants and revokes commit in
// the same serialized way, and access never widens the write paths. Deletes
// are owner-scoped and hard: the record, its chunks and its grants vanish in
// one serialized transaction, a repeat delete misses with 404, the id is free
// to be created again, and the shared content bytes are reclaimed once the
// last completed attachment referencing them is gone.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. Services map it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrPermissionDenied reports that a device's access to a document has been
// revoked. Services map it to 403; nothing is written and no document content
// is exposed. It is a shared verdict produced by the permission service and
// consulted by every service that enforces the gate inside a transaction.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. Services
// map it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. Services map it to 404.
var ErrSessionNotFound = errors.New("session not found")

// DBTX is the subset of *sql.DB and *sql.Tx the services use for their
// serialized work, so judgments made "in the same transaction" (for example a
// permission gate followed by the gated write) run on one concrete connection
// whether the caller holds a transaction or the handle itself.
type DBTX interface {
	Exec(query string, args ...any) (sql.Result, error)
	Query(query string, args ...any) (*sql.Rows, error)
	QueryRow(query string, args ...any) *sql.Row
}

// Store is the durable kernel: one SQLite database handle together with the
// device, session and attachment data it owns.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here. It also keeps every
	// service's transaction serialized on the same connection.
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

// DB returns the underlying handle. The business services use it to open the
// serialized transactions their judgments run in; callers outside the
// internal packages never need it.
func (s *Store) DB() *sql.DB { return s.db }

// Close releases the database handle.
func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0,
	created_seq INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS attachment_access (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	device_id     TEXT NOT NULL,
	authorized    INTEGER NOT NULL,
	granted_seq   INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY (attachment_id, device_id)
);
`)
	if err != nil {
		return err
	}
	if err := s.ensureAttachmentCreatedSeq(); err != nil {
		return err
	}
	return s.ensureAttachmentAccessGrantedSeq()
}

// ensureAttachmentCreatedSeq adds the creation-order column to databases
// created before it existed. Existing rows are backfilled in insertion
// (rowid) order so their relative listing order is unchanged; new rows take
// strictly larger values, so the sequence never reuses a value even after
// the newest attachment is deleted and its id created again.
func (s *Store) ensureAttachmentCreatedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachments)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "created_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachments ADD COLUMN created_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachments SET created_seq = (
			SELECT COUNT(*) FROM attachments older WHERE older.rowid <= attachments.rowid
		)`,
	)
	return err
}

// ensureAttachmentAccessGrantedSeq adds the grant-order column to access
// tables created before it existed. Existing rows are backfilled one past the
// per-attachment maximum in insertion (rowid) order, so surviving grants keep
// a stable relative order; every new grant takes a strictly larger value, even
// after the previously newest grant was revoked, so a re-granted device lists
// at the position of its latest grant and a value is never reused.
func (s *Store) ensureAttachmentAccessGrantedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachment_access)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "granted_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachment_access ADD COLUMN granted_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachment_access SET granted_seq = (
			SELECT rn FROM (
				SELECT rowid AS rid,
				       ROW_NUMBER() OVER (PARTITION BY attachment_id ORDER BY rowid) AS rn
				FROM attachment_access
			) WHERE rid = attachment_access.rowid
		)`,
	)
	return err
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	created, err = RegisterDeviceTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	return created, tx.Commit()
}

// RegisterDeviceTx is RegisterDevice against an existing transaction, so the
// services can resolve the registration layer as the first step of a larger
// serialized transaction (their permission/content gates then share it).
func RegisterDeviceTx(q DBTX, deviceID string) (created bool, err error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := q.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}

// DeviceExistsTx reports whether deviceID is registered, evaluated inside q so
// a service's gate runs on the same transaction as the work it guards.
func DeviceExistsTx(q DBTX, deviceID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// ListSessions returns the page of live session ids owned by deviceID, each
// appearing at most once, sorted lexicographically by id ascending and paged
// by limit/offset as a slice over that fixed order — so with no intervening
// create or delete, successive pages neither repeat nor skip an id, and an
// offset past the end yields an empty (non-nil) slice and no error. An
// unregistered device yields ErrDeviceNotFound and no listing. The read runs
// in one serialized transaction and writes nothing; deleted sessions are
// absent, and a device deregistration removes every session it owned first.
func (s *Store) ListSessions(deviceID string, limit, offset int64) ([]string, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := DeviceExistsTx(tx, deviceID)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, ErrDeviceNotFound
	}

	rows, err := tx.Query(
		`SELECT id FROM sessions WHERE device_id = ?
		 ORDER BY id ASC LIMIT ? OFFSET ?`,
		deviceID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0)
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			_ = rows.Close()
			return nil, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	_ = rows.Close()

	return ids, tx.Commit()
}

// DeleteDeviceTx deregisters deviceID and removes every record it owns, all
// inside the caller's serialized transaction:
//
//   - the device's sessions are hard-deleted, so their session-scoped reads
//     and subscriptions miss from then on;
//   - every attachment it created is removed together with its chunks, its
//     sealed/unfinished state and the access rows other devices held on it;
//   - the read grants the device itself held on other devices' attachments
//     are withdrawn;
//   - the device row is removed last (every child row goes first).
//
// Digest-addressed content is shared across attachments and is reclaimed only
// when no completed attachment still references a digest — exactly the rule
// of a single attachment delete — so another device's attachment with the same
// digest keeps its bytes and one deregistration by itself never reclaims
// shared content. The document permission ledger lives in the authz package
// and clears its own rows against the same transaction through
// DeleteDevicePermissionsTx.
//
// An unknown (never registered or already deregistered) device yields
// ErrDeviceNotFound and writes nothing. Because the whole judgment runs in one
// immediate transaction on the single shared connection, concurrent
// deregistrations of the same device commit at most once and any concurrent
// chunk upload or finish either committed entirely before it or is rejected
// entirely afterward — no half-written record survives.
func DeleteDeviceTx(q DBTX, deviceID string) error {
	exists, err := DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return ErrDeviceNotFound
	}

	// Remember the digests of the device's completed attachments before their
	// rows vanish: each is a candidate for content reclamation once every
	// owned attachment is gone. DISTINCT because several of the device's
	// attachments may share the same digest-addressed content.
	rows, err := q.Query(
		`SELECT DISTINCT sha256 FROM attachments WHERE device_id = ? AND complete = 1`,
		deviceID,
	)
	if err != nil {
		return err
	}
	var digests []string
	for rows.Next() {
		var digest string
		if err := rows.Scan(&digest); err != nil {
			_ = rows.Close()
			return err
		}
		digests = append(digests, digest)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	// Withdraw the read grants this device held on other devices'
	// attachments (rows naming it as the grantee), then remove the access
	// rosters of the attachments it created before the attachment rows those
	// rosters reference are deleted.
	if _, err := q.Exec(
		`DELETE FROM attachment_access WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_access
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_chunks
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachments WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}

	// Reclaim each digest-addressed content only when no surviving completed
	// attachment — owned by another device, or by the deregistered device in
	// an impossible re-read — still references it.
	for _, digest := range digests {
		var stillReferenced bool
		if err := q.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM attachments WHERE sha256 = ? AND complete = 1)`,
			digest,
		).Scan(&stillReferenced); err != nil {
			return err
		}
		if !stillReferenced {
			if _, err := q.Exec(
				`DELETE FROM attachment_contents WHERE sha256 = ?`, digest,
			); err != nil {
				return err
			}
		}
	}

	if _, err := q.Exec(
		`DELETE FROM sessions WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM devices WHERE id = ?`, deviceID,
	); err != nil {
		return err
	}
	return nil
}

// DeviceExists reports whether a live device with deviceID is registered. It
// is the non-transactional counterpart to DeviceExistsTx, used by the
// document-level subscription handlers whose existence verdict runs before
// the WebSocket upgrade rather than inside a write transaction.
func (s *Store) DeviceExists(deviceID string) (bool, error) {
	return DeviceExistsTx(s.db, deviceID)
}

// SessionExists reports whether a live session with sessionID exists.
// Ownership is intentionally not part of this check: session-scoped reads only
// require that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// JSONEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal. It is shared
// verbatim by the change event and CRDT services' idempotency judgments.
func JSONEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

