// Document-level deletion removes every durable row a document owns in the
// change event service: the online change log, the compaction boundary, the
// retained idempotency summaries of trimmed changes, snapshots and restore
// provenance. After the deletion the same document id is a brand-new document:
// an unknown document reads as an empty list at cursor 0, and the next commit
// allocates cursor 1 again, because every row — the boundary included — that
// remembered the old cursor space is gone.
//
// The work runs inside the caller's serialized transaction, sharing it with the
// CRDT state and permission-ledger deletions of the same operation, so a
// document deletion either removes every row or none; a document with no row
// in any of the services misses (ErrDocumentNotFound) and writes nothing.

package events

import (
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// ErrDocumentNotFound reports that a delete targets a document id that has no
// durable data anywhere — it was never created or was already deleted. The
// caller maps it to 404; nothing is written.
var ErrDocumentNotFound = errors.New("document not found")

// DocumentDataExistsTx reports whether the change event service holds any row
// for documentID: an online change, a compaction boundary, a retained
// trimmed-id summary, a snapshot, a snapshot version marker or a restore
// record. It runs inside the caller's transaction so the existence verdict is
// one judgment with the deletion that follows it.
func (s *Service) DocumentDataExistsTx(q store.DBTX, documentID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_identities WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshots WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshot_versions WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM restores WHERE document_id = ?)`,
		documentID, documentID, documentID, documentID, documentID, documentID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// DeleteDocumentDataTx removes every change-event row of documentID inside the
// caller's serialized transaction: the online log and restore records first
// (the rows that reference cursors), then snapshots and their named version
// markers, the retained idempotency summaries and finally the compaction
// boundary. With the boundary gone the cursor space restarts from 1 when the
// id is created again, and with the markers gone a re-created document of the
// same name inherits no version. It does not judge existence — the caller
// checks DocumentDataExistsTx (and the CRDT service's equivalent) once before
// deleting — so it never returns ErrDocumentNotFound on its own.
func (s *Service) DeleteDocumentDataTx(q store.DBTX, documentID string) error {
	stmts := []string{
		`DELETE FROM restores WHERE document_id = ?`,
		`DELETE FROM changes WHERE document_id = ?`,
		`DELETE FROM snapshot_versions WHERE document_id = ?`,
		`DELETE FROM snapshots WHERE document_id = ?`,
		`DELETE FROM change_identities WHERE document_id = ?`,
		`DELETE FROM change_boundaries WHERE document_id = ?`,
	}
	for _, stmt := range stmts {
		if _, err := q.Exec(stmt, documentID); err != nil {
			return err
		}
	}
	return nil
}

// Change-log compaction moves the old end of a document's change log out of
// the online tables without touching the cursor space the log shares with
// every write path.
//
// The compaction boundary is the greatest cursor that has a saved snapshot
// (zero when the document has none): everything at or below it is reproducible
// from a snapshot plus the surviving tail, so those rows leave the online log.
// A trimmed change is not forgotten, though — its id keeps a small canonical
// summary (the originating device, a digest of the payload and, for a restore,
// the snapshot it came from, plus the cursor it was first assigned) so the
// submission layer keeps answering idempotency and conflict exactly as before.
// The summary never participates in reads: pagination, long polling and
// subscriptions simply no longer see the trimmed rows, and the summary's
// fixed size means storage does not grow back to the pre-compaction shape.
//
// Compaction itself is not a change: it allocates no cursor, writes no change
// record and wakes no waiter or subscriber. The cursor space never resets —
// the next allocated cursor is one past the greater of the online maximum and
// the boundary — and the boundary, the summaries and the read results are
// durable across restarts.

package events

import (
	"bytes"
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// CompactChanges moves every change of documentID whose cursor is at or below
// the compaction boundary out of the online log, in one serialized
// transaction, and returns the boundary together with the number of changes
// removed by this call.
//
// The boundary is the greatest cursor with a saved snapshot, or zero when the
// document has no snapshot — compacting a snapshot-less or unknown document
// succeeds and removes nothing. The gate is enforced before any content is
// observed, exactly as in ReplayChanges: an unregistered device yields
// store.ErrDeviceNotFound and a revoked device yields store.ErrPermissionDenied,
// and neither touches any state.
//
// Each trimmed id keeps its canonical summary (device, payload digest, restore
// provenance and first cursor) so re-posting it stays idempotent and a
// differing re-post stays a conflict. Compaction is idempotent: a repeat finds
// the same boundary, trims nothing and reports zero removed. It commits no
// change row, allocates no cursor and notifies no waiter or subscriber.
func (s *Service) CompactChanges(documentID, deviceID string) (boundary, removed int64, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, 0, err
	}
	defer func() { _ = tx.Rollback() }()

	// Registration and permission are enforced before any change content is
	// observed, so a rejected compaction cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return 0, 0, err
		}
	}

	// The boundary is the greatest cursor with a saved snapshot, 0 when the
	// document has none (an unknown document included).
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM snapshots WHERE document_id = ?`,
		documentID,
	).Scan(&boundary); err != nil {
		return 0, 0, err
	}
	stored, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, 0, err
	}
	if boundary <= stored {
		// Nothing new to trim (a repeat compaction, or a snapshot-less
		// document): report the standing boundary and remove nothing.
		return stored, 0, tx.Commit()
	}

	// Collect the rows leaving the online log before deleting them: each one
	// first moves its canonical summary into the identity table.
	type trimmed struct {
		cursor  int64
		id      string
		device  string
		payload []byte
	}
	rows, err := tx.Query(
		`SELECT cursor, id, device_id, payload FROM changes
		 WHERE document_id = ? AND cursor <= ?
		 ORDER BY cursor ASC`,
		documentID, boundary,
	)
	if err != nil {
		return 0, 0, err
	}
	var dropping []trimmed
	for rows.Next() {
		var t trimmed
		if err := rows.Scan(&t.cursor, &t.id, &t.device, &t.payload); err != nil {
			_ = rows.Close()
			return 0, 0, err
		}
		dropping = append(dropping, t)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return 0, 0, err
	}
	_ = rows.Close()

	for _, t := range dropping {
		// A restored change also carries its provenance into the summary, so a
		// repeated restore keeps its idempotency/conflict decision.
		var restoredFrom sql.NullInt64
		err := tx.QueryRow(
			`SELECT snapshot_cursor FROM restores WHERE document_id = ? AND change_id = ?`,
			documentID, t.id,
		).Scan(&restoredFrom)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			restoredFrom = sql.NullInt64{}
		case err != nil:
			return 0, 0, err
		}
		digest, err := payloadDigest(t.payload)
		if err != nil {
			return 0, 0, err
		}
		if _, err := tx.Exec(
			`INSERT OR IGNORE INTO change_identities
				(document_id, id, device_id, digest, cursor, restored_from)
			 VALUES (?, ?, ?, ?, ?, ?)`,
			documentID, t.id, t.device, digest, t.cursor, restoredFrom,
		); err != nil {
			return 0, 0, err
		}
	}

	if _, err := tx.Exec(
		`DELETE FROM restores WHERE document_id = ? AND change_cursor <= ?`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}
	if _, err := tx.Exec(
		`DELETE FROM changes WHERE document_id = ? AND cursor <= ?`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}
	if _, err := tx.Exec(
		`INSERT INTO change_boundaries (document_id, boundary) VALUES (?, ?)
		 ON CONFLICT (document_id) DO UPDATE SET boundary = excluded.boundary`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}

	if err := tx.Commit(); err != nil {
		return 0, 0, err
	}
	// Compaction is not a change: no waiter is woken and no subscriber is
	// signaled, because no new change exists to observe.
	return boundary, int64(len(dropping)), nil
}

// boundaryOfTx returns the stored compaction boundary of documentID, or zero
// when the document was never compacted.
func boundaryOfTx(q store.DBTX, documentID string) (int64, error) {
	var boundary int64
	err := q.QueryRow(
		`SELECT boundary FROM change_boundaries WHERE document_id = ?`,
		documentID,
	).Scan(&boundary)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return 0, nil
	case err != nil:
		return 0, err
	default:
		return boundary, nil
	}
}

// currentCursorTx returns the document's high-water mark: the greatest online
// cursor, or the compaction boundary when every change up to it has left the
// online log. The cursor space never resets, so a fully trimmed document
// continues from its boundary rather than from zero.
func currentCursorTx(tx *sql.Tx, documentID string) (int64, error) {
	var maxOnline int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&maxOnline); err != nil {
		return 0, err
	}
	boundary, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, err
	}
	if boundary > maxOnline {
		maxOnline = boundary
	}
	return maxOnline, nil
}

// payloadDigest renders a payload in the canonical form JSONEqual compares —
// the decoded value re-encoded, so 1 and 1.0 or reordered object keys digest
// alike — and hashes it. The digest is the fixed-size stand-in for the payload
// in a trimmed change's retained summary.
func payloadDigest(payload json.RawMessage) ([]byte, error) {
	var v any
	if err := json.Unmarshal(payload, &v); err != nil {
		return nil, err
	}
	canonical, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	sum := sha256.Sum256(canonical)
	return sum[:], nil
}

// resolveTrimmedIdentity answers the submission question for an id whose
// online row is absent because compaction trimmed it. It returns found=true
// and the id's first cursor when the retained summary matches the incoming
// device and payload (an idempotent re-post), an *ErrConflict when a retained
// summary exists but differs, and found=false when no summary was retained (a
// genuinely new id).
func resolveTrimmedIdentity(tx *sql.Tx, documentID string, c Change) (found bool, cursor int64, err error) {
	var device string
	var digest []byte
	err = tx.QueryRow(
		`SELECT device_id, digest, cursor FROM change_identities WHERE document_id = ? AND id = ?`,
		documentID, c.ID,
	).Scan(&device, &digest, &cursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, 0, nil
	case err != nil:
		return false, 0, err
	}

	incoming, err := payloadDigest(c.Payload)
	if err != nil {
		return false, 0, err
	}
	if device != c.DeviceID || !bytes.Equal(digest, incoming) {
		return false, 0, &ErrConflict{ID: c.ID}
	}
	return true, cursor, nil
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// snapshotExportItem is one element of an export body. The struct field order
// fixes the on-the-wire key order to cursor then state; State is embedded as
// raw JSON so the stored content is emitted verbatim, exactly as the single
// snapshot read emits it.
type snapshotExportItem struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// snapshotExportResponse is the export body with the top-level key order fixed
// to snapshots then count. Snapshots is always a non-nil slice so an empty
// export serializes as [] rather than null.
type snapshotExportResponse struct {
	Snapshots []snapshotExportItem `json:"snapshots"`
	Count     int                  `json:"count"`
}

// handleExportSnapshots is the read-only batch export over a document's
// snapshot collection:
//
//	GET /v1/documents/{documentID}/snapshots?from=0&to=N
//
// from defaults to 0; to absent means no upper bound. Only snapshots whose
// cursor is in the closed [from, to] interval are returned, in ascending
// cursor order, at most one entry per cursor. An unknown document or a range
// without any snapshot is a successful 200 with an empty list and count 0, not
// an error. The handler writes nothing: it creates no snapshot, moves no
// cursor, records no change and notifies the push channels.
func handleExportSnapshots(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	snaps, err := s.ExportSnapshots(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export snapshots")
		return
	}
	writeSnapshotExport(w, snaps)
}

// writeSnapshotExport renders an export result in the shared response shape: a
// single compact JSON line with the snapshots,count key order, each item
// keyed cursor,state, an empty export serializing as [] with count 0. It is
// shared by the document-scoped and session-scoped exports so their bodies
// cannot drift apart.
func writeSnapshotExport(w http.ResponseWriter, snaps []events.ExportedSnapshot) {
	items := make([]snapshotExportItem, 0, len(snaps))
	for _, snap := range snaps {
		items = append(items, snapshotExportItem{Cursor: snap.Cursor, State: snap.State})
	}
	writeJSON(w, http.StatusOK, snapshotExportResponse{Snapshots: items, Count: len(items)})
}

// handleSessionExportSnapshots is the session-scoped view of the snapshot
// batch export, over the session document-read prefix with the resource
// segment swapped to the snapshot collection:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/snapshots?from=0&to=N
//
// The interval semantics and the response body are identical to the
// document-level export; the path offers no other read form, so every GET is
// the export (from/to absent means the default interval). Around the export
// sit the session view's checks in their fixed order — request shape and
// parameters (400), session existence (404), the session device's document
// permission (403) — so a rejected export exposes no snapshot content and
// writes nothing.
func handleSessionExportSnapshots(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed interval parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the session change export's
	// ordering.
	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	snaps, err := s.ExportSnapshots(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export snapshots")
		return
	}
	writeSnapshotExport(w, snaps)
}

// malformedSnapshotPath reports whether p targets the snapshot namespace but
// is not at one of its exact locations:
//
//	GET  /v1/documents/{documentID}/snapshots                    (the batch export)
//	GET  /v1/documents/{documentID}/snapshots/{cursor}          (the single read)
//	*    /v1/documents/{documentID}/snapshots/versions          (named versions)
//	*    /v1/documents/{documentID}/snapshots/versions/{name}
//	POST /v1/documents/{documentID}/snapshots/versions/{name}/restore
//
// A trailing slash (an empty cursor or name segment, including the collection
// path with a trailing slash), extra path segments, or a "snapshots" segment
// in any keyword position short of one of those shapes is a malformed 400
// rather than ServeMux's redirect or plain-text 404/405: the snapshot
// endpoints promise a JSON error and never a redirect. Empty segments are
// already rejected by the guard itself. The keyword is matched only past the
// documentID position, so a document literally named "snapshots" keeps its
// ordinary routes.
func malformedSnapshotPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "snapshots" || i == 0 {
			continue
		}
		// Keyword position reached. The collection is exactly
		// {documentID}/snapshots; the single read adds one non-empty cursor
		// segment; the named-version subtree adds the versions collection, one
		// non-empty name segment, and optionally a trailing restore segment.
		// Anything else (trailing slash, missing/extra segments) is malformed.
		collection := len(segs) == 2 && segs[0] != ""
		cursorItem := len(segs) == 3 && segs[0] != "" && segs[2] != ""
		versionsCollection := len(segs) == 3 && segs[0] != "" && segs[2] == "versions"
		versionsItem := len(segs) == 4 && segs[0] != "" && segs[2] == "versions" && segs[3] != ""
		versionsRestore := len(segs) == 5 && segs[0] != "" && segs[2] == "versions" && segs[3] != "" && segs[4] == "restore"
		return !(collection || cursorItem || versionsCollection || versionsItem || versionsRestore)
	}
	return false
}

// inSessionSnapshotVersionsSubtree reports whether segs (the path split past
// "/v1/sessions/") sits in the named-snapshot-version subtree: a "snapshots"
// collection segment followed by a "versions" segment. The exact shape verdict
// (collection, item, item/restore) belongs to malformedSessionSnapshotsPath;
// every other session keyword guard yields to it so a version name that
// coincides with a change keyword ("poll", "merge", "restore", "subscribe",
// "compact", "query") keeps its version routes rather than being judged as a
// malformed change path.
func inSessionSnapshotVersionsSubtree(segs []string) bool {
	return len(segs) >= 5 &&
		segs[1] == "documents" &&
		segs[3] == "snapshots" &&
		segs[4] == "versions"
}

// malformedSessionSnapshotsPath reports whether p targets the session-scoped
// snapshot namespace but is not at one of its exact locations:
//
//	GET    /v1/sessions/{sessionId}/documents/{documentId}/snapshots                       (batch export)
//	POST   /v1/sessions/{sessionId}/documents/{documentId}/snapshots/versions              (register)
//	GET    /v1/sessions/{sessionId}/documents/{documentId}/snapshots/versions              (list)
//	GET    /v1/sessions/{sessionId}/documents/{documentId}/snapshots/versions/{name}       (read)
//	PUT    /v1/sessions/{sessionId}/documents/{documentId}/snapshots/versions/{name}       (rename)
//	DELETE /v1/sessions/{sessionId}/documents/{documentId}/snapshots/versions/{name}       (delete)
//	POST   /v1/sessions/{sessionId}/documents/{documentId}/snapshots/versions/{name}/restore
//
// extra path segments past any of those shapes (the batch export has no
// single-snapshot item, so a trailing cursor segment is malformed too) are a
// JSON 400 rather than ServeMux's plain-text 404 or a redirect. Empty segments
// (doubled slashes, a trailing slash) are already rejected by the guard itself.
//
// "snapshots" is treated as the collection keyword only in the fourth
// segment, right after the document identifier; a session or document
// identifier literally named "snapshots" occupies an identifier position and
// keeps its ordinary routes.
func malformedSessionSnapshotsPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "snapshots" there is an ordinary identifier, not
	// this collection's keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "snapshots" {
		return false
	}
	nonEmptyIDs := segs[0] != "" && segs[2] != ""
	// Keyword position reached. The batch export is exactly the collection;
	// the named-version subtree adds the versions collection, one non-empty
	// name segment, and optionally a trailing restore segment. Anything past
	// one of those shapes (a trailing cursor on the export, an extra segment,
	// a trailing keyword other than restore) is a malformed 400.
	collection := len(segs) == 4
	versionsCollection := len(segs) == 5 && segs[4] == "versions"
	versionsItem := len(segs) == 6 && segs[4] == "versions" && segs[5] != ""
	versionsRestore := len(segs) == 7 && segs[4] == "versions" && segs[5] != "" && segs[6] == "restore"
	return !nonEmptyIDs || !(collection || versionsCollection || versionsItem || versionsRestore)
}

package server

import (
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// compactChangesRequest is the body of POST .../changes/compact: the same
// device field the CRDT compaction endpoint carries.
type compactChangesRequest struct {
	DeviceID string `json:"deviceId"`
}

// compactChangesResponse is the success body of POST .../changes/compact. The
// struct field order fixes the key order (boundary, then removed), and the
// shared JSON writer emits it as one compact line with a trailing newline.
type compactChangesResponse struct {
	Boundary int64 `json:"boundary"`
	Removed  int64 `json:"removed"`
}

// handleCompactChanges moves the document's changes at or below the
// compaction boundary — the greatest cursor with a saved snapshot, zero when
// the document has none — out of the online change log.
//
// The request contract matches the CRDT compaction endpoint: strict
// application/json, exactly one JSON value, no trailing content and a
// non-empty deviceId — any violation is a 400 JSON error with zero writes.
// The gate then applies in the submission's order: an unregistered device is
// a 404 and a device whose permission for the document was revoked is a 403;
// neither writes anything. A snapshot-less or unknown document compacts
// successfully with boundary 0 and nothing removed.
//
// On success the answer is 200 with one compact JSON line naming the boundary
// and the number of changes this call removed. Compaction is idempotent — a
// repeat reports the same boundary and zero removed — and is not itself a
// change: it allocates no cursor, writes no change record and wakes no waiter
// or subscriber.
func handleCompactChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req compactChangesRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	boundary, removed, err := s.CompactChanges(documentID, req.DeviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact changes")
		}
		return
	}

	writeJSON(w, http.StatusOK, compactChangesResponse{Boundary: boundary, Removed: removed})
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// snapshotVersionRegisterRequest is the body of the collection POST: the
// calling device, the stable version name to create and the existing snapshot
// cursor it is bound to.
type snapshotVersionRegisterRequest struct {
	DeviceID       string          `json:"deviceId"`
	Name           string          `json:"name"`
	SnapshotCursor json.RawMessage `json:"snapshotCursor"`
}

// snapshotVersionBindRequest is the body of the rename (PUT
// .../snapshots/versions/{name}): the calling device and the existing
// snapshot cursor the name is moved onto. The name itself is in the path.
type snapshotVersionBindRequest struct {
	DeviceID       string          `json:"deviceId"`
	SnapshotCursor json.RawMessage `json:"snapshotCursor"`
}

// snapshotVersionRestoreRequest is the body of the by-name restore: the
// calling device and the change id the restored state is appended under. The
// source snapshot is named by the path rather than carried in the body.
type snapshotVersionRestoreRequest struct {
	DeviceID string `json:"deviceId"`
	ChangeID string `json:"changeId"`
}

// snapshotVersionItem fixes the on-the-wire key order of one list entry to
// name then snapshotCursor.
type snapshotVersionItem struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// snapshotVersionListResponse is the list body with the top-level key order
// fixed to versions then count; Versions is always a non-nil slice so an
// empty view serializes as [].
type snapshotVersionListResponse struct {
	Versions []snapshotVersionItem `json:"versions"`
	Count    int                   `json:"count"`
}

// decodeVersionBindRequest enforces the rename endpoint's JSON shape:
// application/json body with a non-empty deviceId and a positive-integer
// snapshotCursor. Every violation is a 400 JSON error and the caller returns
// without touching the store.
func decodeVersionBindRequest(w http.ResponseWriter, r *http.Request) (deviceID string, cursor int64, ok bool) {
	var req snapshotVersionBindRequest
	if !decodeJSONBody(w, r, &req) {
		return "", 0, false
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return "", 0, false
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return "", 0, false
	}
	c, good := parsePositiveInt(req.SnapshotCursor)
	if !good {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return "", 0, false
	}
	return req.DeviceID, c, true
}

// versionDeviceFromQuery resolves the calling device of a bodyless or
// read-only version endpoint from the deviceId query parameter. A missing or
// empty parameter is judged exactly like an unregistered device: a 404 JSON
// error ahead of any version or snapshot observation.
func versionDeviceFromQuery(w http.ResponseWriter, r *http.Request) (string, bool) {
	deviceID := r.URL.Query().Get("deviceId")
	if deviceID == "" {
		writeError(w, http.StatusNotFound, "device not found")
		return "", false
	}
	return deviceID, true
}

// writeVersionGateError maps the shared gate/existence errors of every version
// endpoint onto their fixed status codes, returning true when err was handled.
// The order mirrors the verdict order: device existence (404), permission
// (403), version and snapshot existence (404), conflict (409); none of the
// failure bodies exposes version content.
func writeVersionGateError(w http.ResponseWriter, err error) bool {
	var conflict *events.ErrVersionConflict
	switch {
	case errors.Is(err, store.ErrDeviceNotFound):
		writeError(w, http.StatusNotFound, "device not found")
	case errors.Is(err, store.ErrPermissionDenied):
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
	case errors.Is(err, events.ErrVersionNotFound):
		writeError(w, http.StatusNotFound, "snapshot version not found")
	case errors.Is(err, events.ErrSnapshotNotFound):
		writeError(w, http.StatusNotFound, "snapshot not found")
	case errors.As(err, &conflict):
		writeJSON(w, http.StatusConflict, map[string]string{
			"error":        "snapshot version is already bound to another cursor",
			"conflictName": conflict.Name,
		})
	default:
		return false
	}
	return true
}

// handlePutSnapshotVersion registers an existing snapshot under a stable
// version name:
//
//	POST /v1/documents/{documentID}/snapshots/versions
//
// The name is unique within the document and travels in the JSON body.
// Binding the same name to the same cursor again is idempotent and returns the
// identical body; binding that name to another cursor (or a name another
// cursor occupies) is a 409 with zero writes. The fixed verdict order is
// request shape (400), device existence (404), document permission (403), then
// snapshot and version existence (404) and the conflict verdict (409). Success
// is one compact JSON line naming the version and the snapshot cursor.
func handlePutSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req snapshotVersionRegisterRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Name == "" {
		writeError(w, http.StatusBadRequest, "name must be a non-empty string")
		return
	}
	// snapshotCursor must be present and a positive integer (no fractions,
	// strings, booleans, null or zero).
	if len(req.SnapshotCursor) == 0 {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}
	cursor, ok := parsePositiveInt(req.SnapshotCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
		return
	}

	result, err := s.PutSnapshotVersion(documentID, req.DeviceID, req.Name, cursor)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to register snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// handleListSnapshotVersions is the read-only collection view:
//
//	GET /v1/documents/{documentID}/snapshots/versions?deviceId=D
//
// It returns every registration in ascending version-name order, each entry
// naming only the name and the snapshot cursor; an unknown document (or one
// without markers) reads as an empty array with count 0 rather than an error.
// The calling device must be registered (404) and still authorized (403); the
// read writes nothing and exposes no snapshot state.
func handleListSnapshotVersions(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	deviceID, ok := versionDeviceFromQuery(w, r)
	if !ok {
		return
	}

	versions, err := s.ListSnapshotVersions(documentID, deviceID)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to list snapshot versions")
		}
		return
	}

	items := make([]snapshotVersionItem, 0, len(versions))
	for _, v := range versions {
		items = append(items, snapshotVersionItem{Name: v.Name, Cursor: v.Cursor})
	}
	writeJSON(w, http.StatusOK, snapshotVersionListResponse{Versions: items, Count: len(items)})
}

// handleGetSnapshotVersion reads the snapshot state a version name points at:
//
//	GET /v1/documents/{documentID}/snapshots/versions/{name}?deviceId=D
//
// The body is byte-for-byte the by-cursor snapshot read
// ({"cursor":N,"state":...}): the state is presented exactly as stored. The
// verdict order is shape (400), device existence (404), permission (403),
// version and snapshot existence (404).
func handleGetSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	deviceID, ok := versionDeviceFromQuery(w, r)
	if !ok {
		return
	}

	cursor, state, err := s.GetSnapshotVersionState(documentID, deviceID, name)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to load snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
}

// handleRebindSnapshotVersion moves an existing version name onto another
// existing snapshot:
//
//	PUT /v1/documents/{documentID}/snapshots/versions/{name}
//
// The verdict order is request shape (400), device existence (404), permission
// (403), then the version marker (a missing name is 404) and the target
// snapshot (a missing cursor, an unknown document included, is 404). Rebinding
// to the cursor already bound is an idempotent no-op with the same body. The
// snapshot itself is never modified.
func handleRebindSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	deviceID, cursor, ok := decodeVersionBindRequest(w, r)
	if !ok {
		return
	}

	result, err := s.RebindSnapshotVersion(documentID, deviceID, name, cursor)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to rename snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// handleDeleteSnapshotVersion hard-deletes one version marker:
//
//	DELETE /v1/documents/{documentID}/snapshots/versions/{name}?deviceId=D
//
// The request carries no body. A missing marker is a 404 JSON error; the
// snapshot itself is untouched and, once the deletion commits, the name is
// free to bind again. Success is one compact JSON line naming the version and
// the deletion marker.
func handleDeleteSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	deviceID, ok := versionDeviceFromQuery(w, r)
	if !ok {
		return
	}

	if err := s.DeleteSnapshotVersion(documentID, deviceID, name); err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to delete snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"name": name, "deleted": true})
}

// handleRestoreSnapshotVersion restores the snapshot a version name points at
// as one ordinary change:
//
//	POST /v1/documents/{documentID}/snapshots/versions/{name}/restore
//
// The body names the calling device and the change id; the source snapshot is
// resolved from the path. On a hit the snapshot's state is appended exactly
// like the cursor-based restore in one serialized transaction (the document
// cursor advances by one) and the success body is byte-identical to it.
// Idempotency and conflict follow the existing restore rules: an id occupied
// by an ordinary change is a 409 with zero writes. The verdict order is shape
// (400), device existence (404), permission (403), version and snapshot
// existence (404), then the restore conflict (409).
func handleRestoreSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	name := r.PathValue("name")             // route pattern + guard guarantee non-empty

	var req snapshotVersionRestoreRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.ChangeID == "" {
		writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
		return
	}

	result, err := s.RestoreSnapshotVersion(documentID, req.DeviceID, req.ChangeID, name)
	if err != nil {
		var conflict *events.ErrRestoreConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, events.ErrVersionNotFound):
			writeError(w, http.StatusNotFound, "snapshot version not found")
		case errors.Is(err, events.ErrSnapshotNotFound):
			writeError(w, http.StatusNotFound, "snapshot not found")
		case errors.As(err, &conflict):
			writeJSON(w, http.StatusConflict, map[string]string{
				"error":      "change id already exists with a different deviceId, snapshotCursor or source state",
				"conflictId": conflict.ID,
			})
		default:
			writeError(w, http.StatusInternalServerError, "failed to restore snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

// The device pending-change statistics read is the change event service's
// read-only answer to "for each of this device's documents, how many online
// changes it originated are still outstanding and where does the online log
// end": one row per document that currently carries an online change the
// device originated, each carrying the document id, the count of online rows
// it originated and the largest cursor among them. Like every other read it
// sees only the online change log — the retained summaries in
// change_identities exist for idempotency alone and never participate in
// reads — so a document whose changes were all compacted away, or that was
// deleted outright, no longer appears. The read allocates no cursor and
// notifies no waiter or subscriber.

package events

import (
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// PendingChangeStat is one document's pending-change statistics: the document
// id, the number of online changes that device originated in it (Count, never
// zero for a row that appears) and the largest cursor among those online
// changes (MaxCursor).
type PendingChangeStat struct {
	DocumentID string
	Count      int64
	MaxCursor  int64
}

// ListDevicePendingChanges returns one stat per document that currently
// carries an online change originated by deviceID — the documents the
// device's sessions once wrote changes to and whose change data still exists
// — each appearing at most once, sorted lexicographically by document id
// ascending and paged by limit/offset as a slice over that fixed order. With
// no intervening commit or deletion, successive pages neither repeat nor
// skip an id, and an offset past the end yields an empty (non-nil) slice and
// no error.
//
// The count and the maximum cursor count only the device's changes still in
// the online log, never the retained summaries compaction leaves behind. An
// unregistered device yields store.ErrDeviceNotFound and no statistics. The
// read runs in one serialized transaction and writes nothing: a fully
// compacted document has no online rows and is absent, exactly as a deleted
// document is after its rows were removed.
func (s *Service) ListDevicePendingChanges(deviceID string, limit, offset int64) ([]PendingChangeStat, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, store.ErrDeviceNotFound
	}

	rows, err := tx.Query(
		`SELECT document_id, COUNT(*), MAX(cursor) FROM changes
		 WHERE device_id = ?
		 GROUP BY document_id
		 ORDER BY document_id ASC
		 LIMIT ? OFFSET ?`,
		deviceID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	stats := make([]PendingChangeStat, 0)
	for rows.Next() {
		var stat PendingChangeStat
		if err := rows.Scan(&stat.DocumentID, &stat.Count, &stat.MaxCursor); err != nil {
			_ = rows.Close()
			return nil, err
		}
		stats = append(stats, stat)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	_ = rows.Close()

	return stats, tx.Commit()
}

// The device document listing is the change event service's read-only answer
// to "which documents does this device still have outstanding changes in":
// every document that currently carries an online change the device
// originated, each at most once. Like every other read it sees only the
// online change log — the retained summaries in change_identities exist for
// idempotency alone and never participate in reads — so a document whose
// changes were all compacted away, or that was deleted outright, no longer
// appears. The read allocates no cursor and notifies no waiter or subscriber.

package events

import (
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// ListDeviceDocuments returns the page of document ids that currently carry
// an online change originated by deviceID — the documents the device's
// sessions once wrote changes to and whose change data still exists — each
// appearing at most once, sorted lexicographically by document id ascending
// and paged by limit/offset as a slice over that fixed order. With no
// intervening commit or deletion, successive pages neither repeat nor skip
// an id, and an offset past the end yields an empty (non-nil) slice and no
// error.
//
// An unregistered device yields store.ErrDeviceNotFound and no listing. The
// read runs in one serialized transaction and writes nothing: a fully
// compacted document has no online rows and is absent, exactly as a deleted
// document is after its rows were removed.
func (s *Service) ListDeviceDocuments(deviceID string, limit, offset int64) ([]string, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, store.ErrDeviceNotFound
	}

	rows, err := tx.Query(
		`SELECT DISTINCT document_id FROM changes
		 WHERE device_id = ?
		 ORDER BY document_id ASC
		 LIMIT ? OFFSET ?`,
		deviceID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0)
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			_ = rows.Close()
			return nil, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	_ = rows.Close()

	return ids, tx.Commit()
}

