309		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":3,\"removed\":3}\n" {
310			t.Fatalf("compact = %d %q", w.Code, w.Body.String())
311		}
312	
313		// The trimmed restore replays idempotently from its retained provenance.
314		w, body := postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
315			"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 2,
316		})
317		if w.Code != http.StatusOK {
318			t.Fatalf("trimmed restore replay = %d %s", w.Code, w.Body.String())
319		}
