324		// A different snapshot source for the same id is a 409 with zero writes.
325		w, _ = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
326			"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
327		})
328		if w.Code != http.StatusConflict {
329			t.Fatalf("restore source mismatch = %d %s", w.Code, w.Body.String())
330		}
331	
332		// A trimmed ordinary change id cannot be reused as a restore id.
333		w, _ = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
334			"deviceId": "dev-1", "changeId": "c1", "snapshotCursor": 2,
335		})
336		if w.Code != http.StatusConflict {
337			t.Fatalf("ordinary id as restore = %d %s", w.Code, w.Body.String())
338		}
339	
340		// Snapshot export and reads are untouched by the compaction.
341		w = getRaw(t, h, "/v1/documents/doc/snapshots")
342		if w.Code != http.StatusOK {
343			t.Fatal(w.Body.String())
344		}
345		var exported map[string]any
346		if err := json.Unmarshal(w.Body.Bytes(), &exported); err != nil {
347			t.Fatal(err)
348		}
349		if int64(exported["count"].(float64)) != 3 {
350			t.Fatalf("exported snapshots = %s", w.Body.String())
351		}
