492	func TestChangesCompactRestart(t *testing.T) {
493		dir := t.TempDir()
494		dbPath := filepath.Join(dir, "sync.db")
495	
496		st, err := app.Open(dbPath)
497		if err != nil {
498			t.Fatal(err)
499		}
500		h := NewHandler(st)
501		registerDevice(t, h, "dev-1")
502		postDocChanges(t, h, "doc", "dev-1", 3)
503		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": nil})
504		if w.Code != http.StatusOK {
505			t.Fatal(w.Body.String())
506		}
507		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":2,\"removed\":2}\n" {
508			t.Fatalf("compact = %d %q", w.Code, w.Body.String())
509		}
510		if err := st.Close(); err != nil {
511			t.Fatal(err)
512		}
513	
514		st2, err := app.Open(dbPath)
515		if err != nil {
516			t.Fatal(err)
517		}
518		defer func() { _ = st2.Close() }()
519		h2 := NewHandler(st2)
520	
521		// The boundary, the reads and the idempotency decisions survive the
522		// restart.
523		if w := compactChanges(t, h2, "doc", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":2,\"removed\":0}\n" {
524			t.Fatalf("re-compact after restart = %d %q", w.Code, w.Body.String())
525		}
526		_, body := doRequest(t, h2, http.MethodGet, "/v1/documents/doc/changes?after=0")
527		rows := body["changes"].([]any)
528		if len(rows) != 1 || rows[0].(map[string]any)["id"] != "c3" {
529			t.Fatalf("changes after restart = %v", rows)
530		}
531		w, body = postJSON(t, h2, "/v1/documents/doc/changes", map[string]any{
532			"deviceId": "dev-1",
533			"changes":  []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
534		})
535		if w.Code != http.StatusOK {
536			t.Fatalf("trimmed replay after restart = %d %s", w.Code, w.Body.String())
537		}
538		result := body["results"].([]any)[0].(map[string]any)
539		if result["created"] != false || int64(result["cursor"].(float64)) != 1 {
540			t.Fatalf("trimmed replay result after restart = %v", result)
541		}
542	
543		// New changes continue the pre-compaction cursor space: no reuse, no gap.
544		w, body = postJSON(t, h2, "/v1/documents/doc/changes", map[string]any{
545			"deviceId": "dev-1",
546			"changes":  []any{map[string]any{"id": "c4", "payload": map[string]any{"n": 4}}},
547		})
548		if w.Code != http.StatusOK {
549			t.Fatal(w.Body.String())
550		}
551		result = body["results"].([]any)[0].(map[string]any)
552		if result["created"] != true || int64(result["cursor"].(float64)) != 4 {
553			t.Fatalf("new cursor after restart = %v, want 4", result)
554		}
