557	// After a full trim the snapshot cursor judgment follows the never-reset
558	// cursor space: creating a snapshot for a trimmed cursor still succeeds, a
559	// repeat reports created=false, and a restore of that snapshot keeps its
560	// idempotency — all unchanged across a restart.
561	func TestSnapshotAfterFullTrimHTTP(t *testing.T) {
562		dbPath := filepath.Join(t.TempDir(), "sync.db")
563		open := func(t *testing.T) (http.Handler, *app.App) {
564			t.Helper()
565			s, err := app.Open(dbPath)
566			if err != nil {
567				t.Fatal(err)
568			}
569			return NewHandler(s), s
570		}
571	
572		h, s := open(t)
573		registerDevice(t, h, "dev-1")
574		postDocChanges(t, h, "doc", "dev-1", 2)
575		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": nil})
576		if w.Code != http.StatusOK {
577			t.Fatal(w.Body.String())
578		}
579		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":2,\"removed\":2}\n" {
580			t.Fatalf("full compact = %d %q", w.Code, w.Body.String())
581		}
582	
583		// A trimmed cursor is still an existing cursor: the snapshot is created;
584		// the identical repeat is idempotent.
585		snapshotAtOne := func(h http.Handler) {
586			t.Helper()
587			w, body := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}})
588			if w.Code != http.StatusOK || body["created"] != true {
589				t.Fatalf("snapshot at trimmed cursor = %d %v body=%s", w.Code, body, w.Body.String())
590			}
591			w, body = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}})
592			if w.Code != http.StatusOK || body["created"] != false {
593				t.Fatalf("repeat snapshot = %d %v body=%s", w.Code, body, w.Body.String())
594			}
595			// A cursor beyond the high-water mark is still a 400.
596			w, _ = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 3, "state": nil})
597			if w.Code != http.StatusBadRequest {
598				t.Fatalf("snapshot beyond boundary = %d, want 400", w.Code)
599			}
600		}
601		snapshotAtOne(h)
602	
603		// The new snapshot restores; the repeat restore is idempotent with the
604		// first cursor.
605		restore := func(h http.Handler) {
606			t.Helper()
607			w, body := postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
608				"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
609			})
610			if w.Code != http.StatusOK || body["created"] != true ||
611				int64(body["cursor"].(float64)) != 3 || int64(body["restoredFrom"].(float64)) != 1 {
612				t.Fatalf("restore = %d %v body=%s", w.Code, body, w.Body.String())
613			}
614			w, body = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
615				"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
616			})
617			if w.Code != http.StatusOK || body["created"] != false || int64(body["cursor"].(float64)) != 3 {
618				t.Fatalf("repeat restore = %d %v body=%s", w.Code, body, w.Body.String())
619			}
620		}
621		restore(h)
622		_ = s.Close()
623	
624		// After a restart the snapshot, the restore idempotency and the cursor
625		// judgment are unchanged.
626		h, s = open(t)
627		defer func() { _ = s.Close() }()
628		w, body := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}})
629		if w.Code != http.StatusOK || body["created"] != false {
630			t.Fatalf("snapshot after restart = %d %v body=%s", w.Code, body, w.Body.String())
631		}
632		w, body = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
633			"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 1,
634		})
635		if w.Code != http.StatusOK || body["created"] != false || int64(body["cursor"].(float64)) != 3 {
636			t.Fatalf("restore after restart = %d %v body=%s", w.Code, body, w.Body.String())
637		}
638	}
639	
640	// A trimmed change id that belongs to a restore compares only the source
641	// device and the payload at the ordinary-commit, replay and merge entries —
642	// the restore provenance plays no role there, so re-submitting the id with
643	// the matching device and payload is idempotent, never a 409.
644	func TestTrimmedRestoreIdIgnoresProvenanceOutsideRestore(t *testing.T) {
645		h, _ := newTestHandler(t)
646		registerDevice(t, h, "dev-1")
647		postDocChanges(t, h, "doc", "dev-1", 2)
648		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": map[string]any{"snap": 2}})
649		if w.Code != http.StatusOK {
650			t.Fatal(w.Body.String())
651		}
652		w, _ = postJSON(t, h, "/v1/documents/doc/restore", map[string]any{
653			"deviceId": "dev-1", "changeId": "r1", "snapshotCursor": 2,
654		})
655		if w.Code != http.StatusOK {
656			t.Fatalf("restore: %d %s", w.Code, w.Body.String())
657		}
658		w, _ = postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 3, "state": nil})
659		if w.Code != http.StatusOK {
660			t.Fatal(w.Body.String())
661		}
662		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK || w.Body.String() != "{\"boundary\":3,\"removed\":3}\n" {
663			t.Fatalf("compact = %d %q", w.Code, w.Body.String())
664		}
665	
666		// Ordinary commit: same device and payload as the trimmed restore is
667		// idempotent with the first cursor, not a 409.
668		w, body := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
669			"deviceId": "dev-1",
670			"changes":  []any{map[string]any{"id": "r1", "payload": map[string]any{"snap": 2}}},
671		})
672		if w.Code != http.StatusOK {
673			t.Fatalf("post trimmed restore id = %d %s", w.Code, w.Body.String())
674		}
675		result := body["results"].([]any)[0].(map[string]any)
676		if result["created"] != false || int64(result["cursor"].(float64)) != 3 {
677			t.Fatalf("post result = %v, want created=false cursor 3", result)
678		}
679	
680		// Offline replay: same verdict.
681		w, body = postJSON(t, h, "/v1/documents/doc/replay", map[string]any{
682			"deviceId":   "dev-1",
683			"operations": []any{map[string]any{"id": "r1", "payload": map[string]any{"snap": 2}}},
684		})
685		if w.Code != http.StatusOK {
686			t.Fatalf("replay trimmed restore id = %d %s", w.Code, w.Body.String())
687		}
688		result = body["results"].([]any)[0].(map[string]any)
689		if result["created"] != false || int64(result["cursor"].(float64)) != 3 {
690			t.Fatalf("replay result = %v, want created=false cursor 3", result)
691		}
692	
693		// Merge: same verdict.
694		w, body = postJSON(t, h, "/v1/documents/doc/merge", map[string]any{
695			"deviceId": "dev-1", "baseCursor": 3,
696			"change": map[string]any{"id": "r1", "payload": map[string]any{"snap": 2}},
697		})
698		if w.Code != http.StatusOK {
699			t.Fatalf("merge trimmed restore id = %d %s", w.Code, w.Body.String())
700		}
701		if body["outcome"] != "idempotent" || int64(body["cursor"].(float64)) != 3 {
702			t.Fatalf("merge result = %v, want idempotent cursor 3", body)
703		}
704	
705		// A different device or payload at those entries is still a 409.
706		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
707			"deviceId": "dev-1",
708			"changes":  []any{map[string]any{"id": "r1", "payload": map[string]any{"snap": 99}}},
709		})
710		if w.Code != http.StatusConflict {
711			t.Fatalf("payload mismatch = %d, want 409", w.Code)
712		}
713	}
