// The retained set is the newest n cursors: resolve the oldest retained
// cursor (the n-th row in descending order) and hard-delete every snapshot
// older than it. When fewer than n rows exist that lookup yields no row, so
// the comparison matches nothing and the document is left intact. The whole
// judgment runs on the single serialized connection inside this
// transaction, so a snapshot created concurrently is either entirely among
// the rows this prune observed or not present.
var cutoff sql.NullInt64
if err := tx.QueryRow(
	`SELECT cursor FROM (
		SELECT cursor FROM snapshots
		WHERE document_id = ?
		ORDER BY cursor DESC
		LIMIT 1 OFFSET ?
	 )`,
	documentID, n-1,
).Scan(&cutoff); err != nil {
	return PruneResult{}, err
}

