87		if _, err := s.PruneSnapshots("doc", "ghost", json.RawMessage(`0`)); !errors.Is(err, store.ErrDeviceNotFound) {
88			t.Fatalf("unregistered bad keep err = %v, want ErrDeviceNotFound", err)
89		}
90	
91		// Reauthorize; the invalid keep now surfaces and writes nothing.
92		if _, err := s.SetDocumentPermission("doc", "dev", true); err != nil {
93			t.Fatal(err)
94		}
95		for _, raw := range []string{``, `null`, `0`, `-1`, `1.5`, `2.0`, `"2"`, `true`, `[1]`, `1001`} {
96			if _, err := s.PruneSnapshots("doc", "dev", json.RawMessage(raw)); !errors.Is(err, events.ErrPruneKeepInvalid) {
97				t.Fatalf("keep %q err = %v, want ErrPruneKeepInvalid", raw, err)
98			}
99		}
100		// The boundary values are accepted.
101		if _, err := s.PruneSnapshots("doc", "dev", json.RawMessage(`1`)); err != nil {
102			t.Fatalf("keep 1 err = %v", err)
103		}
104		if _, err := s.PruneSnapshots("doc", "dev", json.RawMessage(`1000`)); err != nil {
105			t.Fatalf("keep 1000 err = %v", err)
106		}
107	}
108	
109	// After compaction deleted the restores row and left only the retained
110	// identity summary, pruning the snapshot a prior restore came from must not
111	// change that restore's idempotency and conflict verdicts: the summary's
112	// provenance answers. A fresh restore of the pruned cursor still misses.
113	func TestPruneSnapshotsAfterCompactionKeepsRestoreVerdict(t *testing.T) {
114		s, err := app.Open("")
115		if err != nil {
116			t.Fatal(err)
117		}
118		defer func() { _ = s.Close() }()
119		if _, err := s.RegisterDevice("dev"); err != nil {
120			t.Fatal(err)
121		}
122		if _, err := s.PostChanges("doc", changes("c1", "c2")); err != nil {
123			t.Fatal(err)
124		}
125		if _, err := s.PutSnapshot("doc", 2, json.RawMessage(`{"from":"s2"}`)); err != nil {
126			t.Fatal(err)
127		}
128		// Restore snapshot 2 as r1 (cursor 3), snapshot the cursor, then compact:
129		// the restore leaves the online log and keeps only the provenance summary.
130		if res, err := s.RestoreSnapshot("doc", "dev", "r1", 2); err != nil || !res.Created || res.Cursor != 3 || res.RestoredFrom != 2 {
131			t.Fatalf("restore = %+v err = %v", res, err)
132		}
133		if _, err := s.PutSnapshot("doc", 3, json.RawMessage(`{"from":"s3"}`)); err != nil {
134			t.Fatal(err)
135		}
136		if boundary, removed, err := s.CompactChanges("doc", "dev"); err != nil || boundary != 3 || removed != 3 {
137			t.Fatalf("compact = %d %d err = %v", boundary, removed, err)
138		}
139	
140		// Add a snapshot at the older cursor 1 (still an existing cursor in the
141		// never-reset space), then keep only the newest snapshot (cursor 3):
142		// snapshots 1 and 2 are pruned.
143		if _, err := s.PutSnapshot("doc", 1, json.RawMessage(`{"from":"s1"}`)); err != nil {
144			t.Fatal(err)
145		}
146		if res, err := s.PruneSnapshots("doc", "dev", json.RawMessage(`1`)); err != nil || res.MaxCursor != 3 || res.Removed != 2 {
147			t.Fatalf("prune = %+v err = %v", res, err)
148		}
149	
150		// The accepted restore is still idempotent from the retained summary even
151		// though its snapshot row is gone: created=false, first cursor 3.
152		res, err := s.RestoreSnapshot("doc", "dev", "r1", 2)
153		if err != nil {
154			t.Fatalf("idempotent restore = %v", err)
155		}
156		if res.Created || res.Cursor != 3 || res.RestoredFrom != 2 {
157			t.Fatalf("idempotent restore = %+v", res)
158		}
159		// A different source cursor for the same id stays a conflict, not a 404.
160		var conflict *events.ErrRestoreConflict
161		if _, err := s.RestoreSnapshot("doc", "dev", "r1", 1); !errors.As(err, &conflict) {
162			t.Fatalf("source mismatch err = %v, want restore conflict", err)
163		}
164		// A fresh id against the pruned snapshot misses.
165		if _, err := s.RestoreSnapshot("doc", "dev", "r2", 2); !errors.Is(err, events.ErrSnapshotNotFound) {
166			t.Fatalf("fresh restore err = %v, want ErrSnapshotNotFound", err)
167		}
